public class OnlineStockSpanTest {

    private OnlineStockSpan stockSpan;

    @Before
    public void setUp() {
        stockSpan = new OnlineStockSpan();
    }

    @Test
    public void next_ReturnsCorrectPrice() {
        int price = 10;
        int expected = 1;
        assertEquals(expected, stockSpan.next(price));
    }

    @Test
    public void next_ReturnsCorrectPriceForMultipleCalls() {
        int price1 = 10;
        int price2 = 20;
        int expected = new int[]{1, 2};
        assertArrayEquals(expected, new int[]{stockSpan.next(price1), stockSpan.next(price2)});
    }

    @Test
    public void calculateSpans_ReturnsCorrectSpansForSinglePrice() {
        int[] prices = {10};
        int[] expected = {1};
        assertArrayEquals(expected, stockSpan.calculateSpans(prices));
    }

    @Test
    public void calculateSpans_ReturnsCorrectSpansForMultiplePrices() {
        int[] prices = {10, 20, 30};
        int[] expected = {1, 2, 3};
        assertArrayEquals(expected, stockSpan.calculateSpans(prices));
    }

    @Test
    public void calculateSpans_ReturnsZeroSpansForEmptyPriceList() {
        int[] prices = {};
        int[] expected = {0};
        assertArrayEquals(expected, stockSpan.calculateSpans(prices));
    }

    private Stack<Integer> stack = new Stack<>();

    @Test
    public void next_ThrowsNullPointerExceptionWhenStackIsEmpty() {
        stockSpan.next(10);
        stockSpan.next(20);
        NullPointerException expect = null;
        try {
            stockSpan.next(30);
        } catch (NullPointerException e) {
            assertEquals(expect, e);
        }
    }

    private int price = 100;

    @Test
    public void next_UpdatesPriceWhenNextIsCalled() {
        stockSpan.next(price);
        int expected = price;
        assertEquals(expected, stockSpan.next(price));
    }

    @Test
    public void calculateSpans_ReturnsCorrectSpansForSinglePriceWhenStackIsEmpty() {
        stack.clear();
        stockSpan.calculateSpans(new int[]{price});
        assertArrayEquals(new int[]{1}, stockSpan.calculateSpans(new int[]{}));
    }
}
